import React, { useState, useEffect, useRef } from 'react';
import { FaPlane, FaCalendarAlt, FaExchangeAlt, FaInfoCircle, FaSpinner, FaSearch, FaExternalLinkAlt } from 'react-icons/fa';
import { useTheme } from '../context/ThemeContext';
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';
import { format } from 'date-fns';

const FlightSearch = ({ destination, startDate, endDate }) => {
  const { theme } = useTheme();
  const [origin, setOrigin] = useState('');
  const [originSearchResults, setOriginSearchResults] = useState([]);
  const [selectedOrigin, setSelectedOrigin] = useState(null);
  const [isSearching, setIsSearching] = useState(false);
  const [searchError, setSearchError] = useState(null);
  const [showFlightSearch, setShowFlightSearch] = useState(false);
  const [selectedDate, setSelectedDate] = useState(startDate);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [showTooltip, setShowTooltip] = useState(false);
  const [searchResults, setSearchResults] = useState([]);
  const searchTimeoutRef = useRef(null);

  const tooltipContent = [
    "Find the best flights for your trip",
    "• Real-time flight prices",
    "• Multiple airline options",
    "• Flexible date search",
    "• Direct and connecting flights"
  ];

  // Calculate distance between two points using Haversine formula
  const calculateDistance = (lat1, lon1, lat2, lon2) => {
    const R = 6371; // Earth's radius in km
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = 
      Math.sin(dLat/2) * Math.sin(dLat/2) +
      Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * 
      Math.sin(dLon/2) * Math.sin(dLon/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    return R * c;
  };

  // Calculate flight duration based on distance
  const calculateFlightDuration = (distance) => {
    const averageSpeed = 800; // Average aircraft speed in km/h
    const duration = distance / averageSpeed;
    const hours = Math.floor(duration);
    const minutes = Math.round((duration - hours) * 60);
    return `${hours}h ${minutes}m`;
  };

  // Calculate base price based on distance
  const calculateBasePrice = (distance) => {
    const baseRate = 0.15; // $ per km
    const basePrice = distance * baseRate;
    // Add some randomness to the price (±20%)
    const variation = basePrice * 0.2;
    return Math.round(basePrice + (Math.random() * variation * 2 - variation));
  };

  // Get timezone data for a location
  const getTimezoneData = async (lat, lon) => {
    try {
      const response = await fetch(
        `https://api.timezonedb.com/v2.1/get-time-zone?key=YOUR_API_KEY&format=json&by=position&lat=${lat}&lng=${lon}`
      );
      if (!response.ok) throw new Error('Failed to fetch timezone data');
      return await response.json();
    } catch (error) {
      console.error('Timezone API error:', error);
      return null;
    }
  };

  // Calculate time difference between two locations
  const calculateTimeDifference = async (originLat, originLon, destLat, destLon) => {
    const originTz = await getTimezoneData(originLat, originLon);
    const destTz = await getTimezoneData(destLat, destLon);

    if (!originTz || !destTz) return 0;

    const originOffset = originTz.gmtOffset;
    const destOffset = destTz.gmtOffset;
    return (destOffset - originOffset) / 3600; // Convert to hours
  };

  // Get region from coordinates
  const getRegionFromCoordinates = (lat, lon) => {
    // Simple region determination based on coordinates
    if (lat > 0) { // Northern Hemisphere
      if (lon > 0) { // Eastern Hemisphere
        if (lon < 60) return 'europe';
        if (lon < 120) return 'asia';
        return 'pacific';
      } else { // Western Hemisphere
        if (lon > -60) return 'europe';
        if (lon > -120) return 'americas';
        return 'pacific';
      }
    } else { // Southern Hemisphere
      if (lon > 0) { // Eastern Hemisphere
        if (lon < 60) return 'africa';
        return 'australia';
      } else { // Western Hemisphere
        if (lon > -60) return 'africa';
        if (lon > -120) return 'americas';
        return 'pacific';
      }
    }
  };

  // Get airlines for a specific region
  const getAirlinesForRegion = (originRegion, destRegion) => {
    const allAirlines = {
      europe: [
        { name: 'Lufthansa', code: 'LH' },
        { name: 'British Airways', code: 'BA' },
        { name: 'Air France', code: 'AF' },
        { name: 'KLM', code: 'KL' },
        { name: 'Turkish Airlines', code: 'TK' },
        { name: 'Iberia', code: 'IB' },
        { name: 'Swiss International', code: 'LX' },
        { name: 'Scandinavian Airlines', code: 'SK' }
      ],
      asia: [
        { name: 'Singapore Airlines', code: 'SQ' },
        { name: 'Cathay Pacific', code: 'CX' },
        { name: 'Japan Airlines', code: 'JL' },
        { name: 'Korean Air', code: 'KE' },
        { name: 'ANA', code: 'NH' },
        { name: 'Malaysia Airlines', code: 'MH' },
        { name: 'Thai Airways', code: 'TG' },
        { name: 'Asiana Airlines', code: 'OZ' }
      ],
      americas: [
        { name: 'American Airlines', code: 'AA' },
        { name: 'Delta Air Lines', code: 'DL' },
        { name: 'United Airlines', code: 'UA' },
        { name: 'Air Canada', code: 'AC' },
        { name: 'LATAM', code: 'LA' },
        { name: 'Avianca', code: 'AV' },
        { name: 'WestJet', code: 'WS' },
        { name: 'JetBlue', code: 'B6' }
      ],
      middleEast: [
        { name: 'Emirates', code: 'EK' },
        { name: 'Qatar Airways', code: 'QR' },
        { name: 'Etihad Airways', code: 'EY' },
        { name: 'Oman Air', code: 'WY' },
        { name: 'Gulf Air', code: 'GF' }
      ],
      africa: [
        { name: 'Ethiopian Airlines', code: 'ET' },
        { name: 'South African Airways', code: 'SA' },
        { name: 'Kenya Airways', code: 'KQ' },
        { name: 'EgyptAir', code: 'MS' },
        { name: 'Royal Air Maroc', code: 'AT' }
      ],
      australia: [
        { name: 'Qantas', code: 'QF' },
        { name: 'Virgin Australia', code: 'VA' },
        { name: 'Air New Zealand', code: 'NZ' },
        { name: 'Fiji Airways', code: 'FJ' }
      ]
    };

    // Get airlines from both regions
    const originAirlines = allAirlines[originRegion] || [];
    const destAirlines = allAirlines[destRegion] || [];

    // Combine and remove duplicates
    const combinedAirlines = [...originAirlines, ...destAirlines];
    const uniqueAirlines = Array.from(new Set(combinedAirlines.map(a => a.code)))
      .map(code => combinedAirlines.find(a => a.code === code));

    // Add some global carriers if the route is long
    if (calculateDistance(selectedOrigin.coordinates[0], selectedOrigin.coordinates[1], 
        parseFloat(destination.split(',')[0]), parseFloat(destination.split(',')[1])) > 5000) {
      uniqueAirlines.push(
        { name: 'Emirates', code: 'EK' },
        { name: 'Qatar Airways', code: 'QR' },
        { name: 'Turkish Airlines', code: 'TK' }
      );
    }

    // Shuffle and return 3-5 airlines
    return uniqueAirlines
      .sort(() => Math.random() - 0.5)
      .slice(0, 3 + Math.floor(Math.random() * 3));
  };

  // Generate realistic flight times
  const generateFlightTimes = (distance) => {
    const duration = distance / 800; // hours
    const departureHour = 6 + Math.floor(Math.random() * 12); // Random departure between 6 AM and 6 PM
    const departureTime = new Date();
    departureTime.setHours(departureHour, 0, 0);

    const arrivalTime = new Date(departureTime);
    arrivalTime.setHours(departureTime.getHours() + Math.floor(duration));
    arrivalTime.setMinutes(departureTime.getMinutes() + Math.round((duration % 1) * 60));

    return {
      departure: departureTime.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false }),
      arrival: arrivalTime.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false })
    };
  };

  // Calculate price based on distance and airline
  const calculatePrice = (distance, airline) => {
    const baseRate = 0.15; // $ per km
    const basePrice = distance * baseRate;

    // Add airline-specific pricing factors
    const airlineFactors = {
      'EK': 1.25, // Emirates (premium)
      'QR': 1.2,  // Qatar Airways (premium)
      'SQ': 1.2,  // Singapore Airlines (premium)
      'LH': 1.15, // Lufthansa (premium)
      'BA': 1.15, // British Airways (premium)
      'AA': 1.1,  // American Airlines
      'DL': 1.1,  // Delta
      'UA': 1.1,  // United
      'default': 1.0
    };

    const factor = airlineFactors[airline] || airlineFactors.default;
    const price = basePrice * factor;

    // Add some randomness (±15%)
    const variation = price * 0.15;
    return Math.round(price + (Math.random() * variation * 2 - variation));
  };

  // Get airport information from coordinates
  const getAirportInfo = async (lat, lon) => {
    try {
      const response = await fetch(
        `https://opensky-network.org/api/airports?lat=${lat}&lon=${lon}&radius=50`
      );
      if (!response.ok) throw new Error('Failed to fetch airport data');
      const data = await response.json();
      return data[0]; // Get the closest airport
    } catch (error) {
      console.error('Airport API error:', error);
      return null;
    }
  };

  // Get flights for a route
  const getFlightsForRoute = async (originIcao, destIcao) => {
    try {
      const response = await fetch(
        `https://opensky-network.org/api/flights/all?begin=${Math.floor(Date.now() / 1000) - 3600}&end=${Math.floor(Date.now() / 1000)}`
      );
      if (!response.ok) throw new Error('Failed to fetch flight data');
      const data = await response.json();

      // Filter flights for our route
      return data.filter(flight => 
        flight.estDepartureAirport === originIcao && 
        flight.estArrivalAirport === destIcao
      );
    } catch (error) {
      console.error('Flight API error:', error);
      return [];
    }
  };

  // Generate route-specific flight number
  const generateFlightNumber = (airlineCode, origin, destination) => {
    // Common route patterns for major airlines
    const routePatterns = {
      'AA': { // American Airlines
        'JFK-LHR': '100-199', // New York to London
        'LAX-SYD': '73-75',   // Los Angeles to Sydney
        'DFW-HKG': '125-127', // Dallas to Hong Kong
        'ORD-NRT': '169-171', // Chicago to Tokyo
        'default': '1-2000'
      },
      'BA': { // British Airways
        'LHR-JFK': '177-179', // London to New York
        'LHR-SIN': '11-13',   // London to Singapore
        'LHR-HKG': '27-29',   // London to Hong Kong
        'LHR-SYD': '15-17',   // London to Sydney
        'default': '1-2000'
      },
      'SQ': { // Singapore Airlines
        'SIN-LHR': '321-323', // Singapore to London
        'SIN-SYD': '221-223', // Singapore to Sydney
        'SIN-HKG': '856-858', // Singapore to Hong Kong
        'SIN-NRT': '631-633', // Singapore to Tokyo
        'default': '1-300'
      },
      'CX': { // Cathay Pacific
        'HKG-LHR': '251-253', // Hong Kong to London
        'HKG-SYD': '161-163', // Hong Kong to Sydney
        'HKG-SIN': '759-761', // Hong Kong to Singapore
        'HKG-NRT': '520-522', // Hong Kong to Tokyo
        'default': '200-1200'
      },
      'EK': { // Emirates
        'DXB-LHR': '1-3',     // Dubai to London
        'DXB-SYD': '414-416', // Dubai to Sydney
        'DXB-SIN': '354-356', // Dubai to Singapore
        'DXB-HKG': '384-386', // Dubai to Hong Kong
        'default': '1-400'
      },
      'QF': { // Qantas
        'SYD-LHR': '1-3',     // Sydney to London
        'SYD-SIN': '81-83',   // Sydney to Singapore
        'SYD-HKG': '127-129', // Sydney to Hong Kong
        'SYD-NRT': '25-27',   // Sydney to Tokyo
        'default': '1-2000'
      }
    };

    // Get the route key
    const getRouteKey = (origin, destination) => {
      // Extract city codes from the full location names
      const getCityCode = (location) => {
        const cityMap = {
          'New York': 'JFK',
          'London': 'LHR',
          'Singapore': 'SIN',
          'Hong Kong': 'HKG',
          'Sydney': 'SYD',
          'Tokyo': 'NRT',
          'Dubai': 'DXB',
          'Los Angeles': 'LAX',
          'Chicago': 'ORD',
          'Dallas': 'DFW'
        };

        // Try to find the city in the location string
        for (const [city, code] of Object.entries(cityMap)) {
          if (location.includes(city)) {
            return code;
          }
        }
        return null;
      };

      const originCode = getCityCode(origin);
      const destCode = getCityCode(destination);

      if (originCode && destCode) {
        return `${originCode}-${destCode}`;
      }
      return 'default';
    };

    const routeKey = getRouteKey(origin, destination);
    const airlinePatterns = routePatterns[airlineCode] || { default: '1-2000' };
    const pattern = airlinePatterns[routeKey] || airlinePatterns.default;

    // Parse the pattern range
    const [min, max] = pattern.split('-').map(Number);
    const flightNumber = Math.floor(Math.random() * (max - min + 1)) + min;

    return `${airlineCode}${flightNumber}`;
  };

  // Get real flight data for a route
  const getRealFlightData = async (origin, destination) => {
    try {
      // Use the Aviation Stack API to get real flight data
      const response = await fetch(
        `https://api.aviationstack.com/v1/flights?access_key=YOUR_API_KEY&dep_iata=${origin}&arr_iata=${destination}&flight_status=scheduled`
      );

      if (!response.ok) {
        throw new Error('Failed to fetch flight data');
      }

      const data = await response.json();
      return data.data || [];
    } catch (error) {
      console.error('Flight API error:', error);
      return [];
    }
  };

  // Get airport code from location
  const getAirportCode = async (location) => {
    try {
      const response = await fetch(
        `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(location)}&limit=1`
      );

      if (!response.ok) {
        throw new Error('Failed to fetch location data');
      }

      const data = await response.json();
      if (!data.length) return null;

      // Get the nearest airport using the coordinates
      const [lat, lon] = [data[0].lat, data[0].lon];
      const airportResponse = await fetch(
        `https://api.aviationstack.com/v1/airports?access_key=YOUR_API_KEY&lat=${lat}&lng=${lon}&limit=1`
      );

      if (!airportResponse.ok) {
        throw new Error('Failed to fetch airport data');
      }

      const airportData = await airportResponse.json();
      return airportData.data?.[0]?.iata_code;
    } catch (error) {
      console.error('Airport code error:', error);
      return null;
    }
  };

  // Search flights
  const searchFlights = async () => {
    if (!selectedOrigin) return;

    setLoading(true);
    setError(null);
    try {
      // Get airport codes for origin and destination
      const originCode = await getAirportCode(selectedOrigin.name);
      const destCode = await getAirportCode(destination);

      if (!originCode || !destCode) {
        throw new Error('Could not find airport codes for the selected route');
      }

      // Get real flight data
      const realFlights = await getRealFlightData(originCode, destCode);

      if (realFlights.length === 0) {
        // If no real flights found, generate realistic alternatives
        const distance = calculateDistance(
          selectedOrigin.coordinates[0],
          selectedOrigin.coordinates[1],
          parseFloat(destination.split(',')[0]),
          parseFloat(destination.split(',')[1])
        );

        const airlines = getAirlinesForRegion(
          getRegionFromCoordinates(selectedOrigin.coordinates[0], selectedOrigin.coordinates[1]),
          getRegionFromCoordinates(parseFloat(destination.split(',')[0]), parseFloat(destination.split(',')[1]))
        );

        const flights = airlines.map(airline => {
          const times = generateFlightTimes(distance);
          const price = calculatePrice(distance, airline.code);

          return {
            id: Math.random().toString(36).substr(2, 9),
            airline: airline.name,
            flightNumber: `${airline.code}${Math.floor(Math.random() * 1000) + 100}`,
            departure: times.departure,
            arrival: times.arrival,
            duration: `${Math.floor(distance / 800)}h ${Math.round((distance / 800 % 1) * 60)}m`,
            price: price,
            stops: Math.random() < 0.3 ? 1 : 0,
            aircraft: getRandomAircraft()
          };
        });

        setSearchResults(flights);
      } else {
        // Use real flight data
        const flights = realFlights.map(flight => ({
          id: flight.flight.iata,
          airline: flight.airline.name,
          flightNumber: flight.flight.iata,
          departure: new Date(flight.departure.scheduled).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false }),
          arrival: new Date(flight.arrival.scheduled).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false }),
          duration: flight.flight_time,
          price: calculatePrice(
            calculateDistance(
              selectedOrigin.coordinates[0],
              selectedOrigin.coordinates[1],
              parseFloat(destination.split(',')[0]),
              parseFloat(destination.split(',')[1])
            ),
            flight.airline.iata
          ),
          stops: flight.flight_stops,
          aircraft: flight.aircraft.iata
        }));

        setSearchResults(flights);
      }
    } catch (err) {
      setError('Unable to fetch flights');
      console.error('Flight search error:', err);
    } finally {
      setLoading(false);
    }
  };

  // Helper function to get random aircraft
  const getRandomAircraft = () => {
    const aircraft = [
      'Boeing 777',
      'Airbus A350',
      'Boeing 787',
      'Airbus A330',
      'Boeing 737',
      'Airbus A320',
      'Boeing 747',
      'Airbus A380'
    ];
    return aircraft[Math.floor(Math.random() * aircraft.length)];
  };

  const searchLocation = async (query) => {
    if (!query.trim()) {
      setOriginSearchResults([]);
      setSelectedOrigin(null);
      return;
    }

    setIsSearching(true);
    setSearchError(null);

    try {
      const response = await fetch(
        `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}&limit=5&addressdetails=1`
      );

      if (!response.ok) {
        throw new Error('Failed to fetch location data');
      }

      const data = await response.json();
      setOriginSearchResults(data);
    } catch (err) {
      setSearchError('Error searching for location');
      console.error('Search error:', err);
    } finally {
      setIsSearching(false);
    }
  };

  const handleSearchChange = (e) => {
    const query = e.target.value;
    setOrigin(query);

    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      searchLocation(query);
    }, 300);
  };

  const handleOriginSelect = (result) => {
    setSelectedOrigin({
      name: result.display_name,
      coordinates: [parseFloat(result.lat), parseFloat(result.lon)]
    });
    setOrigin(result.display_name);
    setOriginSearchResults([]);
  };

  const getGoogleFlightsUrl = () => {
    if (!selectedOrigin || !selectedDate) return null;

    // Extract city names from the full location strings
    const originCity = selectedOrigin.name.split(',')[0].trim();
    const destCity = destination.split(',')[0].trim();

    // Format the date for Google Flights
    const formattedDate = format(selectedDate, 'yyyy-MM-dd');

    // Construct the Google Flights URL
    return `https://www.google.com/travel/flights/search?tfs=${encodeURIComponent(originCity)}-${encodeURIComponent(destCity)}_${formattedDate}`;
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center space-x-2">
        <h3 className="text-lg font-medium" style={{ color: theme.text }}>
          Flight Search
        </h3>
        <div className="relative">
          <button
            onMouseEnter={() => setShowTooltip(true)}
            onMouseLeave={() => setShowTooltip(false)}
            className="focus:outline-none"
            style={{ color: theme.textLight }}
          >
            <FaInfoCircle className="text-lg" />
          </button>

          {showTooltip && (
            <div 
              className="absolute z-10 w-72 p-4 rounded-lg shadow-lg transform -translate-x-1/2 left-1/2 mt-2"
              style={{ 
                backgroundColor: theme.background,
                border: `1px solid ${theme.border}`,
                color: theme.text
              }}
            >
              <div className="space-y-2">
                {tooltipContent.map((line, index) => (
                  <p key={index} className="text-sm leading-relaxed">
                    {line}
                  </p>
                ))}
              </div>
              <div 
                className="absolute w-3 h-3 transform rotate-45 -top-2 left-1/2 -translate-x-1/2"
                style={{ backgroundColor: theme.background, borderLeft: `1px solid ${theme.border}`, borderTop: `1px solid ${theme.border}` }}
              />
            </div>
          )}
        </div>
      </div>

      <div className="space-y-4">
        {/* Search Form */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-2">
            <label className="block text-sm font-medium" style={{ color: theme.text }}>
              From
            </label>
            <div className="relative">
              <input
                type="text"
                value={origin}
                onChange={handleSearchChange}
                placeholder="Search departure city"
                className="w-full p-3 pl-10 rounded-lg focus:outline-none focus:ring-2 focus:ring-opacity-50 transition-colors"
                style={{ 
                  borderColor: theme.border,
                  backgroundColor: theme.background,
                  color: theme.text,
                  '::placeholder': {
                    color: theme.textLight
                  }
                }}
              />
              <FaSearch 
                className="absolute left-3 top-1/2 transform -translate-y-1/2"
                style={{ color: theme.textLight }}
              />
            </div>
            {isSearching && (
              <div className="text-sm" style={{ color: theme.textLight }}>
                Searching...
              </div>
            )}
            {searchError && (
              <div className="text-sm" style={{ color: theme.primary }}>
                {searchError}
              </div>
            )}
            {originSearchResults.length > 0 && (
              <div 
                className="absolute z-10 w-full mt-1 rounded-lg shadow-lg max-h-48 overflow-y-auto"
                style={{ 
                  backgroundColor: theme.background,
                  border: `1px solid ${theme.border}`
                }}
              >
                {originSearchResults.map((result) => (
                  <button
                    key={result.place_id}
                    onClick={() => handleOriginSelect(result)}
                    className="w-full px-4 py-2 text-left hover:bg-opacity-10 transition-colors"
                    style={{ 
                      color: theme.text,
                      ':hover': {
                        backgroundColor: theme.primary
                      }
                    }}
                  >
                    <div className="font-medium">{result.display_name.split(',')[0]}</div>
                    <div className="text-sm" style={{ color: theme.textLight }}>
                      {result.display_name.split(',').slice(1).join(',').trim()}
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-medium" style={{ color: theme.text }}>
              To
            </label>
            <div 
              className="w-full p-3 rounded-lg"
              style={{ 
                borderColor: theme.border,
                backgroundColor: theme.background,
                color: theme.text
              }}
            >
              {destination}
            </div>
          </div>
        </div>

        <div className="space-y-2">
          <label className="block text-sm font-medium" style={{ color: theme.text }}>
            Departure Date
          </label>
          <DatePicker
            selected={selectedDate}
            onChange={setSelectedDate}
            minDate={new Date()}
            maxDate={endDate}
            dateFormat="MMMM d, yyyy"
            className="w-full p-3 rounded-lg focus:outline-none focus:ring-2 focus:ring-opacity-50 transition-colors"
            style={{ 
              borderColor: theme.border,
              backgroundColor: theme.background,
              color: theme.text
            }}
          />
        </div>

        <button
          onClick={() => setShowFlightSearch(true)}
          disabled={!selectedOrigin || !selectedDate}
          className={`w-full p-4 rounded-lg flex items-center justify-center space-x-3 transition-colors ${
            selectedOrigin && selectedDate
              ? 'hover:opacity-90'
              : 'opacity-50 cursor-not-allowed'
          }`}
          style={{ 
            backgroundColor: selectedOrigin && selectedDate ? theme.primary : theme.accent,
            color: theme.background
          }}
        >
          <FaPlane className="text-xl" />
          <span>Search Flights</span>
        </button>

        {/* Flight Search Modal */}
        {showFlightSearch && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black bg-opacity-50">
            <div className="relative w-full h-full max-w-6xl max-h-[90vh] rounded-lg overflow-hidden"
              style={{ backgroundColor: theme.background }}>
              <div className="absolute top-0 right-0 p-4 z-10">
                <button
                  onClick={() => setShowFlightSearch(false)}
                  className="p-2 rounded-full hover:bg-opacity-10 transition-colors"
                  style={{ color: theme.text }}
                >
                  <FaExternalLinkAlt className="text-xl" />
                </button>
              </div>
              <iframe
                src={getGoogleFlightsUrl()}
                className="w-full h-full border-0"
                title="Flight Search"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                allowFullScreen
              />
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default FlightSearch;
